function comm_h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function comm_boot(mysqli $db):void{
 $db->query("CREATE TABLE IF NOT EXISTS guild_channels (channel_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,guild_id INT NOT NULL,channel_name VARCHAR(80) NOT NULL,channel_topic VARCHAR(180) NOT NULL DEFAULT '',is_archived TINYINT(1) NOT NULL DEFAULT 0,created_by INT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(channel_id),UNIQUE KEY uq_guild_channel(guild_id,channel_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->query("CREATE TABLE IF NOT EXISTS guild_messages (guild_message_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,channel_id BIGINT UNSIGNED NOT NULL,guild_id INT NOT NULL,from_uid INT NOT NULL,body TEXT NOT NULL,is_deleted TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(guild_message_id),KEY idx_guild_messages_channel(channel_id,guild_message_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->query("CREATE TABLE IF NOT EXISTS guild_message_reads (channel_id BIGINT UNSIGNED NOT NULL,uid INT NOT NULL,last_read_message_id BIGINT UNSIGNED NOT NULL DEFAULT 0,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(channel_id,uid)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->query("CREATE TABLE IF NOT EXISTS message_preferences (uid INT NOT NULL PRIMARY KEY,allow_private_messages TINYINT(1) NOT NULL DEFAULT 1,allow_guild_messages TINYINT(1) NOT NULL DEFAULT 1,muted_until DATETIME NULL,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $db->query("CREATE TABLE IF NOT EXISTS communication_moderation (moderation_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,guild_id INT NULL,message_type ENUM('private','guild') NOT NULL,message_id BIGINT UNSIGNED NOT NULL,moderator_uid INT NOT NULL,action_type ENUM('hide','restore','mute') NOT NULL,reason VARCHAR(255) NOT NULL DEFAULT '',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(moderation_id),KEY idx_comm_mod_message(message_type,message_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
}
comm_boot($db);$u=$db->query('SELECT uname,allyid FROM users WHERE uid='.$uid.' LIMIT 1')->fetch_assoc();$guild=(int)($u['allyid']??0);$action=(string)($_REQUEST['atype']??'inbox');$notice='';$error='';
