 elseif($action==='send_guild'){$body=trim((string)($_POST['body']??''));$channel=(int)($_POST['channel_id']??0);if($guild<=0)$error='You are not assigned to a guild.';elseif($body==='')$error='Guild message cannot be empty.';else{$q=$db->prepare('SELECT channel_id FROM guild_channels WHERE channel_id=? AND guild_id=? AND is_archived=0 LIMIT 1');$q->bind_param('ii',$channel,$guild);$q->execute();if(!$q->get_result()->fetch_assoc())$error='Guild channel not found.';else{$st=$db->prepare('INSERT INTO guild_messages (channel_id,guild_id,from_uid,body) VALUES (?,?,?,?)');$st->bind_param('iiis',$channel,$guild,$uid,$body);$st->execute();$notice='Guild message posted.';$action='guild';}}}
}
if($guild>0){$db->query("INSERT IGNORE INTO guild_channels (guild_id,channel_name,channel_topic,created_by) VALUES ($guild,'Command Channel','Guild command and operations',$uid),($guild,'General','Guild-wide discussion',$uid)");}
