}elseif($action==='guild'){if($guild<=0)echo '<section class="comm-card"><h4>No Guild Assignment</h4><p>Join or create a guild before using guild communications.</p></section>';else{$rows=$db->query('SELECT gm.*,u.uname,c.channel_name FROM guild_messages gm INNER JOIN users u ON u.uid=gm.from_uid INNER JOIN guild_channels c ON c.channel_id=gm.channel_id WHERE gm.guild_id='.$guild.' AND gm.is_deleted=0 ORDER BY gm.guild_message_id DESC LIMIT 80');echo '<div class="comm-grid"><section class="comm-card"><h4>Guild Channels</h4>';while($c=$channels->fetch_assoc())echo '<p><b>'.comm_h($c['channel_name']).'</b><br><span class="comm-meta">'.comm_h($c['channel_topic']).'</span></p>';echo '</section><section class="comm-card"><h4>Post to Guild</h4><form method="post" action="modules/communications.php?time='.time().'&atype=send_guild"><input type="hidden" name="csrf" value="'.comm_h($csrf).'"/><label>Channel<select name="channel_id" required>'; $channels2=$db->query('SELECT channel_id,channel_name FROM guild_channels WHERE guild_id='.$guild.' AND is_archived=0');while($c=$channels2->fetch_assoc())echo '<option value="'.(int)$c['channel_id'].'">'.comm_h($c['channel_name']).'</option>';echo '</select></label><label>Message<textarea name="body" rows="5" maxlength="5000" required></textarea></label><button class="comm-btn">Post Guild Message</button></form></section></div><section class="comm-card"><h4>Guild Channel History</h4>';while($r=$rows->fetch_assoc())echo '<div class="comm-msg"><b>'.comm_h($r['uname']).'</b> <span class="comm-meta">'.comm_h($r['channel_name']).' · '.comm_h($r['created_at']).'</span><div>'.nl2br(comm_h($r['body'])).'</div></div>';echo '</section>';}}
